/* ---- 10. Broad jump (airborne, travels) ----
   Ground phases pin the toe to the floor; the flight arcs the hip between the take-off
   and landing positions. Reset fades out and back in at the start line. */
(() => {
  const FLOOR = 266, T0 = 70, T1 = 186, APEX = 24;
  const arms = (ua, fa) => ({ uaN: ua, faN: fa, uaF: ua + 3, faF: fa + 3 });
  const K = (trunk, head, thigh, shin, foot, ua, fa, at) => Object.assign({ trunk, head, thighN: thigh, shinN: shin, footN: foot, thighF: thigh, shinF: shin, footF: foot, at }, arms(ua, fa));
  const keys = {
    set:     K(4, 2, 179, 181, 90, 182, 178, 0),
    load:    K(48, 28, 118, 212, 90, 244, 236, 0),
    takeoff: K(30, 14, 197, 201, 152, 36, 28, 0),
    tuck:    K(26, 12, 96, 172, 112, 58, 50, 0.5),
    land:    K(22, 10, 138, 200, 118, 84, 78, 1), // toes first, then roll to the heel
    stick:   K(42, 22, 106, 216, 90, 96, 88, 1),
  };
  // hip position that puts this pose's toe on the given mark and its lowest point on the floor
  const hipOn = (p, tx) => {
    const J0 = solveSide(Object.assign({}, p, { anchor: [0, 0] }), "hip");
    return [tx - J0.toeN[0], FLOOR - soleY(J0, "N")];
  };
  const H0 = hipOn(keys.takeoff, T0), H1 = hipOn(keys.land, T1);
  SET2.push({
    id: "broad-jump", name: "Broad Jumps", tone: "calisthenics", day: "Calisthenics Legs", code: "CL", view: "SIDE",
    tip: "Swing the arms, jump forward for distance, land soft with bent knees. Replaces box jumps: same hip power, nothing to trip over. Reset fully between reps, this is a power exercise not conditioning.",
    video: "https://www.youtube.com/results?search_query=broad+jump+technique",
    frame: { k: 1.0, cx: 150, cy: 178 },
    keys,
    seq: [
      { label: "Set", dur: 0.6, from: "set", to: "set", effort: 0.2 },
      { label: "Load", dur: 0.7, from: "set", to: "load", ease: "inOut", effort: 0.6 },
      { label: "Drive", dur: 0.3, from: "load", to: "takeoff", ease: "inOut", effort: 1 },
      { label: "Fly", dur: 0.55, from: "takeoff", via: "tuck", to: "land", ease: "inOut", effort: 0.5 },
      { label: "Land", dur: 0.3, from: "land", to: "stick", ease: "out", effort: 0.9 },
      { label: "Stick", dur: 0.7, from: "stick", to: "stick", effort: 0.5 },
      { label: "Reset", dur: 0.9, from: "stick", to: "set", effort: 0.1 },
    ],
    ghostKey: "stick",
    ghostFor: near => (near === "land" || near === "stick") ? "set" : "stick",
    muscles: { glutes: 1, quads: 1, hams: 0.5, calves: 0.5 },
    build(p, ctx) {
      const label = ctx.seg ? ctx.seg.label : "";
      let pose, opacity = 1;
      if (label === "Fly") {
        const t = ctx.pt;
        pose = Object.assign({}, p, { anchor: [lerp(H0[0], H1[0], t), lerp(H0[1], H1[1], t) - APEX * 4 * t * (1 - t)] });
      } else if (label === "Reset") {
        const t = ctx.pt;
        if (t < 0.35) { opacity = 1 - t / 0.35; pose = Object.assign({}, keys.stick, { anchor: hipOn(keys.stick, T1) }); }
        else { opacity = (t - 0.35) / 0.65; pose = Object.assign({}, keys.set, { anchor: hipOn(keys.set, T0) }); }
      } else {
        pose = Object.assign({}, p, { anchor: hipOn(p, p.at >= 0.5 ? T1 : T0) });
      }
      const J = solveSide(pose, "hip");
      const landed = label === "Land" || label === "Stick";
      const soft = landed && (180 - jointAngle(J.hip, J.kneeN, J.ankleN)) > 45;
      const heel1 = T1 - 17, dy = FLOOR + 12;
      const dim = [
        pth(`M${T0} ${FLOOR + 5}V${dy + 4}M${heel1} ${FLOOR + 5}V${dy + 4}M${T0} ${dy}H${heel1}`, "cue" + (landed ? " on" : ""), "stroke-dasharray:none"),
        pth(`M${T0 + 5} ${dy - 2.5}L${T0} ${dy}L${T0 + 5} ${dy + 2.5}M${heel1 - 5} ${dy - 2.5}L${heel1} ${dy}L${heel1 - 5} ${dy + 2.5}`, "cue" + (landed ? " on" : ""), "stroke-dasharray:none"),
      ];
      const shadowX = J.hip[0] + 6, air = Math.max(0, FLOOR - 8 - soleY(J, "N") + 8);
      const els = drawSide(J, ctx.mus, {
        back: [...floorEls(FLOOR, 30, 270), floorShadow(ctx, shadowX, FLOOR, 30 - Math.min(14, air * 0.5), 1 - Math.min(0.6, air * 0.03)), ...dim],
      });
      return { els, J, opacity, labels: [
        { at: [(T0 + heel1) / 2, dy + 10], text: "DISTANCE", on: landed, anchor: "middle" },
        { at: [J.kneeN[0] + 10, J.kneeN[1] - 6], text: soft ? "LAND SOFT" : "", on: soft, anchor: "start" },
      ] };
    },
  });
})();

