/* =========================================================
   PHASE 1: front view of a bent-over and a horizontal body (3D)
   ========================================================= */

// poses across the whole loop, for calibrate3
function sampleKeys(fig, n = 40) {
  const out = [];
  for (const q of fig.seq) for (let i = 0; i <= n / fig.seq.length; i++) {
    const t = i / (n / fig.seq.length);
    out.push(lerpObj(fig.keys[q.from], fig.keys[q.to], t));
  }
  return out;
}
// scale one side's muscles by a weight, so a one-sided move lights one side
function sideMus(mus, wR, wL) {
  const o = {};
  for (const k in mus) {
    const v = mus[k];
    if (typeof v !== "object") { o[k] = v; continue; }
    const w = /R$/.test(k) ? wR : /L$/.test(k) ? wL : 1;
    if (w <= 0.02) continue;
    o[k] = { o: r1(v.o * w), h: r1(v.h * w) };
  }
  return o;
}
// floor seen from a raised camera: front edge with ticks, a faint back edge
function floor3(cam, zFront, zBack, x0 = -110, x1 = 110) {
  const f = cam.P([0, 0, zFront]), b = cam.P([0, 0, zBack]);
  void b;
  return floorEls(f[1], 150 + x0, 150 + x1);
}

/* ---- Rear delt flyes (FRONT, raised camera, hinged torso) ----
   Hinge with a flat back, soft knees, dumbbells under the chest, palms in.
   Raise out to the sides until the arms are about parallel to the floor. (BarBend) */
(() => {
  const cam = camera3(16, 150, 250, -34);
  const TH = 70;                                  // torso about 20° above horizontal, near parallel
  const s = [0, Math.cos(TH * D2R), Math.sin(TH * D2R)];
  const PELVIS = [0, 85.7, -26];                  // hips back, so the hands hang over the forefoot
  const SH = sg => a3(a3(PELVIS, m3(s, B.sh)), [sg * 17.5, 0, 0]);
  const R = 61;                                   // shoulder to grip with a slight, fixed elbow bend
  const gripAt = (sg, phi) => a3(SH(sg), [sg * R * Math.sin(phi * D2R), -R * Math.cos(phi * D2R), -2 * Math.sin(phi * D2R)]);
  const spec = p => {
    const arms = {}, legs = {};
    for (const [S, sg] of [["R", 1], ["L", -1]]) {
      arms[S] = { at: gripAt(sg, p.phi), pole: [sg * Math.cos(p.phi * D2R), Math.sin(p.phi * D2R), -0.45] };
      legs[S] = { ankle: [sg * 11, 8.4, 0], pole: [sg * 0.15, 0, 1], foot: [sg * 0.12, 0, 1] };
    }
    return { pelvis: PELVIS, spine: s, head: 18, arms, legs };
  };
  const FIG = {
    id: "rear-delt-flyes", name: "Rear Delt Flyes", tone: "hypertrophy", day: "Pull B", code: "B2", view: "3/4 FRONT",
    frame: { k: 1.42, cx: 150, cy: 186 },
    keys: { down: { phi: 2 }, up: { phi: 86 } },
    seq: [
      { label: "Raise", dur: 1, from: "down", to: "up", ease: "inOut", effort: 1 },
      { label: "Squeeze", dur: 1, from: "up", to: "up", effort: 1 },
      { label: "Lower", dur: 2, from: "up", to: "down", ease: "inOut", effort: 0.7 },
      { label: "Reset", dur: 0.4, from: "down", to: "down", effort: 0.3 },
    ],
    ghostKey: "up",
    muscles: { delts: 1, midback: 0.55 },
    build(p, ctx) {
      const J = solve3(spec(p));
      const P = cam.P, Dp = cam.depth;
      const items = [];
      for (const S of ["R", "L"]) items.push({ depth: Dp(J["grip" + S]) + 3, tag: "db" + S, els: hexEnd(P(J["grip" + S]), 7.4, "iron") });
      const level = p.phi >= 80;
      const back = [...floor3(cam, 22, -60), floorShadow(ctx, P([0, 0, -6])[0], P([0, 0, -6])[1], 48, 0.85, 0.6),
        cueLine(cam.P(a3(SH(-1), [-82, 0, 0])), cam.P(a3(SH(1), [82, 0, 0])), level)];
      const els = back.concat(draw3D(J, cam, ctx.mus, items));
      const top = P(J.T(0.45, 0, -14));
      return { els, J, labels: [
        { at: add(cam.P(a3(SH(-1), [-82, 0, 0])), [2, -6]), text: "ARMS PARALLEL", on: level, anchor: "start" },
        { at: [top[0] + 4, top[1] - 12], text: "SQUEEZE", on: ctx.phase === "Squeeze", anchor: "middle" },
      ] };
    },
  };
  calibrate3(cam, k => FIG.build(k, { mus: { __id: "cal" }, phase: "", pt: 0, seg: null, uid: "cal" }).J, sampleKeys(FIG));
  FIGS.push(FIG);
})();

/* ---- Archer push-ups (FRONT, raised camera, horizontal body) ----
   Wide hands; shift onto one side as you lower, the working arm bends to about
   90°, the other arm stays straight. Alternate sides, slowly. (NASM, FORGE tip) */
(() => {
  const cam = camera3(40, 150, 250);
  const HAND_X = 55, A = [0, 13, -131], BODY = B.sh + B.thigh + B.shin - 1.2; // a hair of knee slack so the toes never slide
  const HAND = sg => n3([sg * 0.2, -0.15, 1]);
  const centre = p => {
    const dy = p.sy - A[1], dz = Math.sqrt(Math.max(1, BODY * BODY - p.sx * p.sx - dy * dy));
    return [p.sx, p.sy, A[2] + dz];
  };
  const spec = p => {
    const Sc = centre(p), s = n3(s3(Sc, A));
    const arms = {}, legs = {};
    for (const [S, sg] of [["R", 1], ["L", -1]]) {
      arms[S] = { at: [sg * HAND_X, 4, 0], pole: [sg * 0.55, 0.45, -0.7], wrist: true, hand: HAND(sg) };
      legs[S] = { ankle: [sg * 9, A[1], A[2]], pole: [0, -1, 0], foot: [0, -0.7, 0.7], sole: [0, -0.7, -0.7] };
    }
    return { pelvis: a3(Sc, m3(s, -B.sh)), spine: s, head: 6, arms, legs };
  };
  const top = { sx: 0, sy: 46.5, wR: 0, wL: 0 };
  // bottom: shoulders at 30 cm, shifted until the far arm is straight but still inside its reach,
  // so the planted hand never has to slide
  let SX = 0;
  { let lo = 0, hi = 30;
    for (let i = 0; i < 40; i++) {
      const m = (lo + hi) / 2, J = solve3(spec({ sx: m, sy: 30 }));
      if (l3(s3(J.shL, [-HAND_X, 4, 0])) > B.ua + B.fa - 0.12) hi = m; else lo = m;
    }
    SX = lo; }
  const FIG = {
    id: "archer-pushup", name: "Archer Push-Ups", tone: "calisthenics", day: "Calisthenics Push", code: "CP", view: "FRONT · HIGH",
    frame: { k: 1.6, cx: 150, cy: 196 },
    keys: { top, right: { sx: SX, sy: 30, wR: 1, wL: 0 }, left: { sx: -SX, sy: 30, wR: 0, wL: 1 } },
    seq: [
      { label: "Right", dur: 2.2, from: "top", to: "right", ease: "inOut", effort: 0.85 },
      { label: "Press", dur: 1.1, from: "right", to: "top", ease: "inOut", effort: 1 },
      { label: "Top", dur: 0.4, from: "top", to: "top", effort: 0.3 },
      { label: "Left", dur: 2.2, from: "top", to: "left", ease: "inOut", effort: 0.85 },
      { label: "Press", dur: 1.1, from: "left", to: "top", ease: "inOut", effort: 1 },
      { label: "Top", dur: 0.4, from: "top", to: "top", effort: 0.3 },
    ],
    ghostKey: "right",
    ghostFor: near => (near === "top" ? "right" : "top"),
    muscles: { tricepsR: 1, tricepsL: 1, deltsR: 0.6, deltsL: 0.6 },
    build(p, ctx) {
      const J = solve3(spec(p));
      const P = cam.P;
      // the side being worked lights; on the way back up it stays lit until the top
      const wR = Math.max(p.wR, 0), wL = Math.max(p.wL, 0);
      const mus = ctx.ghost ? ctx.mus : sideMus(ctx.mus, wR, wL);
      const work = wR >= wL ? "R" : "L", other = work === "R" ? "L" : "R", ww = Math.max(wR, wL);
      const bend = angle3(J["sh" + work], J["elbow" + work], J["wrist" + work]);
      const straight = angle3(J["sh" + other], J["elbow" + other], J["wrist" + other]);
      const deep = ww > 0.85 && bend <= 96, held = ww > 0.4 && straight >= 168;
      const E = P(J["elbow" + work]), Sh = P(J["sh" + work]), W = P(J["wrist" + work]);
      const items = [{ depth: cam.depth(J["elbow" + work]) + 5, tag: "cue", els: ww > 0.4 ? [pth(protractor(E, Sh, W, 8), "cue" + (deep ? " on" : ""))] : [] }];
      const els = [...floor3(cam, 16, -150), floorShadow(ctx, 150, P([0, 0, -62])[1], 40, 0.75, 1.45)].concat(draw3D(J, cam, mus, items));
      const sgW = work === "R" ? 1 : -1, oS = P(J["elbow" + other]);
      return { els, J, labels: [
        { at: [E[0] + sgW * 8, E[1] + 13], text: ww > 0.4 ? `${Math.round(bend)}°` : "", on: deep, anchor: sgW > 0 ? "start" : "end" },
        { at: [oS[0] - sgW * 6, oS[1] - 12], text: ww > 0.4 ? "STRAIGHT ARM" : "", on: held, anchor: sgW > 0 ? "end" : "start" },
      ] };
    },
  };
  calibrate3(cam, k => FIG.build(k, { mus: { __id: "cal" }, phase: "", pt: 0, seg: null, uid: "cal" }).J, sampleKeys(FIG));
  FIGS.push(FIG);
})();

/* =========================================================
   PHASE 2 · BATCH 1: lying face up on a bench (3D, side-on)
   The 3D body gives true arm foreshortening (elbows flare toward
   the camera); side-on it borrows the 2D torso and head profiles.
   World: x toward the feet, y up, z toward the camera. Floor y = 0.
   ========================================================= */
const BENCH = { top: 44, pad: 6 };
const SUPINE_LAT = [0, 0, -1];            // lat = -z, so the chest faces up and L is the near side
const FLOOR_B = 258;

// flat bench pad and frame, side-on
function flatBenchEls(P, x0, x1) {
  const t = P([x0, BENCH.top, 0]), b = P([x1, BENCH.top - BENCH.pad, 0]);
  const yF = P([0, 0, 0])[1];
  return [
    pth(`M${r1(P([x0 + 10, 0, 0])[0])} ${r1(b[1])}V${r1(yF)}M${r1(P([x1 - 10, 0, 0])[0])} ${r1(b[1])}V${r1(yF)}`, "line-dim"),
    pth(roundRect(Math.min(t[0], b[0]) + 6, yF - 3, Math.abs(b[0] - t[0]) - 12, 3, 1), "iron-dim"),
    pth(roundRect(Math.min(t[0], b[0]), t[1], Math.abs(b[0] - t[0]), b[1] - t[1], 2), "iron"),
  ];
}
// incline: seat pad plus a back pad along the spine, with a frame to the floor
function inclineBenchEls(P, J, seatX0, seatX1, seatTop) {
  const back = m3(J.ant, -1), s = J.s;
  const base = a3(J.T(-0.12, 0, 0), m3(back, 0));
  // back pad: a slab whose top surface sits just under the torso's back line
  const offs = 11.6;
  const q = [[-0.16, 0], [1.3, 0], [1.3, 6], [-0.16, 6]].map(([t, d]) => P(a3(a3(J.pelvis, m3(s, t * B.trunk)), m3(back, offs + d))));
  void base;
  const sTop = P([seatX0, seatTop, 0]), sBot = P([seatX1, seatTop - BENCH.pad, 0]);
  const yF = P([0, 0, 0])[1];
  const footOfBack = P(a3(J.pelvis, a3(m3(s, 1.0 * B.trunk), m3(back, offs + 6))));
  return [
    pth(`M${r1(sBot[0] - 8)} ${r1(sBot[1])}V${r1(yF)}M${r1(footOfBack[0])} ${r1(footOfBack[1])}L${r1(footOfBack[0] + 6)} ${r1(yF)}M${r1(sTop[0] + 6)} ${r1(sBot[1])}L${r1(footOfBack[0] + 4)} ${r1(footOfBack[1] + 20)}`, "line-dim"),
    pth(roundRect(footOfBack[0] - 6, yF - 3, sBot[0] - footOfBack[0] + 8, 3, 1), "iron-dim"),
    pth(poly(q), "iron"),
    pth(roundRect(sTop[0], sTop[1], sBot[0] - sTop[0], sBot[1] - sTop[1], 2), "iron"),
  ];
}
// rack upright with a J-hook, behind the lifter
function uprightEls(P, x, hookY) {
  const top = P([x, hookY + 10, 0]), hook = P([x, hookY, 0]), yF = P([0, 0, 0])[1];
  return [
    pth(roundRect(top[0] - 2.5, top[1], 5, yF - top[1], 1), "iron-dim"),
    pth(`M${r1(hook[0] + 2.5)} ${r1(hook[1] + 3)}H${r1(hook[0] + 9)}V${r1(hook[1] - 3)}`, "line-dim"),
  ];
}
// barbell end-on: plate behind the body (so the chest stays readable), hub in front
function barEnd(P, at) {
  const c = P(at);
  return {
    back: { depth: -999, tag: "plate", els: [pth(circle(c, 22.5), "iron-glass"), pth(circle(c, 15.5), "line-dim")] },
    front: { depth: 999, tag: "hub", els: [pth(circle(c, 3.8), "iron"), pth(circle(c, 1.5), "dot")] },
  };
}
// feet planted on the floor, knees up; returns legs spec
function plantedLegs(ankleX) {
  const o = {};
  for (const [S, sg] of [["R", 1], ["L", -1]]) o[S] = { ankle: [ankleX - 6, 8.4, -sg * 12], pole: [1, 1, 0], foot: [1, 0, 0] };
  return o;
}
// arms gripping a bar point (both hands share x, y; split along z)
function barArms(J0, bar, half, flare) {
  const o = {};
  for (const [S, sg] of [["R", 1], ["L", -1]]) {
    const out = m3(J0.lat, sg);
    o[S] = { at: [bar[0], bar[1], out[2] * half], pole: a3([0.45, -1, 0], m3(out, flare)) };
  }
  return o;
}
// shared rep: lower (controlled), touch, press, lockout
const PRESS_SEQ = (down = 2, pause = 0.2) => [
  { label: "Lower", dur: down, from: "top", to: "bot", ease: "inOut", effort: 0.75 },
  { label: "Touch", dur: pause, from: "bot", to: "bot", effort: 0.9 },
  { label: "Press", dur: 1, from: "bot", to: "top", ease: "inOut", effort: 1 },
  { label: "Lockout", dur: 0.5, from: "top", to: "top", effort: 0.3 },
];
// bar path: up-and-back first, then straight up (Stronger by Science): x moves as d²
const barPath = (top, bot, d) => [lerp(top[0], bot[0], d * d), lerp(top[1], bot[1], d)];
function pathTrace(P, top, bot) {
  let d = "";
  for (let i = 0; i <= 16; i++) { const q = P(a3([...barPath(top, bot, i / 16), 0], [0, 0, 0])); d += (i ? "L" : "M") + P2(q); }
  return d;
}
const P2 = q => r1(q[0]) + " " + r1(q[1]);
function frameStub(J) { return J; }

/* ---- Flat barbell bench press ---- */
function makeFlatPress(o) {
  const cam = camera3(0, 150, FLOOR_B, 0);
  const PELVIS = [o.pelvisX, BENCH.top + 12.4, 0];
  const S = n3([-1, -0.07, 0]);                       // shoulders a touch lower: the arch is in the low back
  const base = solve3({ pelvis: PELVIS, spine: S, lat: SUPINE_LAT, head: -12, arms: { R: { at: [0, 100, 0], pole: [0, -1, 0] }, L: { at: [0, 100, 0], pole: [0, -1, 0] } }, legs: plantedLegs(o.pelvisX + 34) });
  const SH = base.shoulder;
  const TOP = [SH[0] + 1, SH[1] + 61];                // locked out over the shoulders
  const touchSurf = base.T(o.touchT, 0, 12.6);
  const BOT = [touchSurf[0], touchSurf[1] + 2.6];     // bar resting on the chest
  const spec = p => {
    const bar = barPath(TOP, BOT, p.d);
    return { pelvis: PELVIS, spine: S, lat: SUPINE_LAT, head: -12, arms: barArms(base, bar, o.grip, o.flare), legs: plantedLegs(o.pelvisX + 34) };
  };
  const P = cam.P;
  const FIG = {
    id: o.id, name: o.name, view: "SIDE",
    frame: { k: 1.42, cx: 168, cy: 188 },
    keys: { top: { d: 0 }, bot: { d: 1 } },
    seq: PRESS_SEQ(2, o.pause || 0.2),
    ghostKey: "bot",
    muscles: o.muscles,
    build(p, ctx) {
      const J = solve3(spec(p));
      const bar = [...barPath(TOP, BOT, p.d), 0];
      const be = barEnd(P, bar);
      const touch = p.d > 0.97, locked = p.d < 0.03;
      const back = [...floorEls(P([0, 0, 0])[1], 30, 270), floorShadow(ctx, P([o.pelvisX - 10, 0, 0])[0], P([0, 0, 0])[1], 70, 0.8),
        ...uprightEls(P, SH[0] - 16, TOP[1] + 4), ...flatBenchEls(P, o.pelvisX - 96, o.pelvisX + 22),
        pth(pathTrace(P, TOP, BOT), "cue" + (ctx.phase === "Press" ? " on" : ""))];
      const els = back.concat(draw3D(J, cam, ctx.mus, [be.back, be.front]));
      const tp = P([BOT[0], BOT[1], 0]), lk = P([TOP[0], TOP[1], 0]);
      return { els, J, labels: [
        { at: [tp[0] + 26, tp[1] - 30], text: o.touchLabel, on: touch, anchor: "start" },
        { at: [lk[0] + 26, lk[1] - 6], text: "OVER SHOULDERS", on: locked, anchor: "start" },
        ...(o.extraLabel ? [o.extraLabel(J, p, ctx, P)] : []),
      ] };
    },
  };
  calibrate3(cam, k => FIG.build(k, { mus: { __id: "cal" }, phase: "", pt: 0, seg: null, uid: "cal" }).J, sampleKeys(FIG));
  FIGS.push(FIG);
}

makeFlatPress({
  id: "bb-flat-bench", name: "Barbell Flat Bench Press", pelvisX: 40, touchT: 0.72, grip: 25, flare: 0.75,
  touchLabel: "LOWER CHEST", muscles: { chest: 1, triceps: 0.55, frontdelt: 0.5 },
});
makeFlatPress({
  id: "cg-bench-press", name: "Close-Grip Bench Press", pelvisX: 40, touchT: 0.68, grip: 18, flare: 0.22, pause: 0.35,
  touchLabel: "NO BOUNCE", muscles: { triceps: 1, chest: 0.55, frontdelt: 0.45 },
  extraLabel: (J, p, ctx, P) => { const lp = P([30, 24, 0]); return { at: [lp[0], lp[1]], text: "ELBOWS TUCKED", on: p.d > 0.6, anchor: "middle" }; },
});

/* ---- Incline presses: bench at 30° (FORGE tip; NASM says 45, tip wins) ---- */
function makeIncline(o) {
  const cam = camera3(0, 150, FLOOR_B, 0);
  const ANG = 30, SEAT = 46;
  const PELVIS = [44, SEAT + 12.4, 0];
  const S = n3([-Math.cos(ANG * D2R), Math.sin(ANG * D2R), 0]);
  const legs = (() => { const l = {}; for (const [Sd, sg] of [["R", 1], ["L", -1]]) l[Sd] = { ankle: [44 + 38, 8.4, -sg * 12], pole: [1, 1, 0], foot: [1, 0, 0] }; return l; })();
  const base = solve3({ pelvis: PELVIS, spine: S, lat: SUPINE_LAT, head: -6, arms: { R: { at: [0, 120, 0], pole: [0, -1, 0] }, L: { at: [0, 120, 0], pole: [0, -1, 0] } }, legs });
  const SH = base.shoulder;
  const spec = p => ({ pelvis: PELVIS, spine: S, lat: SUPINE_LAT, head: -6, arms: o.arms(base, p), legs });
  const P = cam.P;
  const FIG = {
    id: o.id, name: o.name, view: "SIDE",
    frame: { k: 1.34, cx: 160, cy: 176 },
    keys: { top: { d: 0 }, bot: { d: 1 } },
    seq: o.seq,
    ghostKey: "bot",
    muscles: o.muscles,
    build(p, ctx) {
      const J = solve3(spec(p));
      const yF = P([0, 0, 0])[1];
      // 30° gauge at the hinge between seat and back pad
      const hinge = P(a3(J.T(-0.14, 0, 0), m3(J.ant, -14.5)));
      const r = 34, a0 = [hinge[0] - r, hinge[1]], a1 = [hinge[0] - r * Math.cos(ANG * D2R), hinge[1] - r * Math.sin(ANG * D2R)];
      const gauge = pth(`M${P2(a0)}A${r} ${r} 0 0 1 ${P2(a1)}`, "cue on");
      const items = o.items(J, p, P);
      const back = [...floorEls(yF, 30, 270), floorShadow(ctx, P([20, 0, 0])[0], yF, 64, 0.8),
        ...(o.rack ? uprightEls(P, SH[0] - 22, o.rack) : []),
        ...inclineBenchEls(P, J, 44 - 16, 44 + 26, SEAT), gauge];
      const els = back.concat(draw3D(J, cam, ctx.mus, items));
      return { els, J, labels: [
        { at: [a0[0] - 8, a0[1] - 4], text: "30°", on: true, anchor: "end" },
        ...o.labels(J, p, ctx, P),
      ] };
    },
  };
  calibrate3(cam, k => FIG.build(k, { mus: { __id: "cal" }, phase: "", pt: 0, seg: null, uid: "cal" }).J, sampleKeys(FIG));
  FIGS.push(FIG);
  return { base, SH };
}

// incline barbell: lockout straight over the shoulders, touch the upper chest below the collarbone
(() => {
  let TOP, BOT;
  const r = makeIncline({
    id: "incline-bb-press", name: "Incline Barbell Press",
    seq: PRESS_SEQ(2, 0.2),
    muscles: { chest: 1, frontdelt: 0.6, triceps: 0.5 },
    arms: (base, p) => {
      if (!TOP) {
        const sh = base.shoulder, up = base.T(0.88, 0, 11.4);
        TOP = [sh[0] + 1, sh[1] + 61];
        BOT = [up[0] + base.ant[0] * 2.6, up[1] + base.ant[1] * 2.6];
      }
      return barArms(base, barPath(TOP, BOT, p.d), 25, 0.75);
    },
    rack: 0,
    items: (J, p, P) => { const be = barEnd(P, [...barPath(TOP, BOT, p.d), 0]); return [be.back, be.front]; },
    labels: (J, p, ctx, P) => {
      const tp = P([BOT[0], BOT[1], 0]), lk = P([TOP[0], TOP[1], 0]);
      return [
        { at: [tp[0] + 24, tp[1] - 26], text: "UPPER CHEST", on: p.d > 0.97, anchor: "start" },
        { at: [lk[0] + 26, lk[1] - 6], text: "OVER SHOULDERS", on: p.d < 0.03, anchor: "start" },
      ];
    },
  });
  void r;
})();

// incline dumbbell: DBs beside the upper chest at the bottom, stacked over the shoulders at the top, no clank
(() => {
  makeIncline({
    id: "db-incline-press", name: "Dumbbell Incline Press",
    seq: [
      { label: "Lower 3s", dur: 3, from: "top", to: "bot", ease: "inOut", effort: 0.75 },
      { label: "Press", dur: 1, from: "bot", to: "top", ease: "inOut", effort: 1 },
      { label: "Squeeze", dur: 0.6, from: "top", to: "top", effort: 0.8 },
    ],
    muscles: { chest: 1, frontdelt: 0.6, triceps: 0.45 },
    arms: (base, p) => {
      const o = {};
      for (const [Sd, sg] of [["R", 1], ["L", -1]]) {
        const out = m3(base.lat, sg), sh = base["sh" + Sd];
        const bot = a3(a3(base.T(0.86, 0, 10), m3(out, 26)), m3(base.s, -2));
        const top = a3(a3(sh, [0, 60, 0]), m3(out, -4));
        o[Sd] = { at: mix3(top, bot, p.d), pole: a3([0.4, -1, 0], m3(out, 0.85)) };
      }
      return o;
    },
    items: (J, p, P) => {
      const out = [];
      for (const Sd of ["R", "L"]) {
        const g = J["grip" + Sd], near = Sd === "L";
        out.push({ depth: near ? 998 : -998, tag: "db" + Sd, els: hexEnd(P(g), 8.2, near ? "iron" : "iron-dim") });
      }
      return out;
    },
    labels: (J, p, ctx, P) => {
      // depth: elbows drop below the line of the bench back
      const e = J.elbowL, pad = a3(J.pelvis, m3(J.ant, -11.6));
      const below = d3(s3(e, pad), J.ant) < 0;
      const ep = P(e);
      void ep;
      const lp = P([20, 24, 0]);
      return [{ at: [lp[0], lp[1]], text: "ELBOWS BELOW BENCH", on: below && p.d > 0.9, anchor: "middle" }];
    },
  });
})();

/* ---- Supine neck flexion: head off the end of the bench, shoulders stay down ---- */
(() => {
  const cam = camera3(0, 150, FLOOR_B, 0);
  const PELVIS = [62, BENCH.top + 12.4, 0];
  const S = n3([-1, -0.05, 0]);
  const legs = plantedLegs(62 + 34);
  const base = solve3({ pelvis: PELVIS, spine: S, lat: SUPINE_LAT, head: 0, arms: { R: { at: [0, 100, 0], pole: [0, -1, 0] }, L: { at: [0, 100, 0], pole: [0, -1, 0] } }, legs });
  const benchEnd = base.shoulder[0] + 4;              // bench stops at the shoulders; head and neck hang free
  // hands hold the bench edges beside the hips
  const arms = {};
  for (const [Sd, sg] of [["R", 1], ["L", -1]]) {
    const out = m3(base.lat, sg);
    arms[Sd] = { at: a3([PELVIS[0] - 6, BENCH.top - 2, 0], m3(out, 21)), pole: a3([0.2, 0.3, 0], m3(out, 1)) };
  }
  const spec = p => ({ pelvis: PELVIS, spine: S, lat: SUPINE_LAT, head: p.h, arms, legs });
  const P = cam.P;
  const FIG = {
    id: "supine-neck-flexion", name: "Supine Neck Flexion", view: "SIDE",
    frame: { k: 1.32, cx: 196, cy: 196 },
    keys: { down: { h: 30 }, up: { h: -74 } },
    seq: [
      { label: "Tuck", dur: 1.4, from: "down", to: "up", ease: "inOut", effort: 1 },
      { label: "Hold", dur: 0.6, from: "up", to: "up", effort: 1 },
      { label: "Slow down", dur: 2.6, from: "up", to: "down", ease: "inOut", effort: 0.7 },
      { label: "Rest", dur: 0.5, from: "down", to: "down", effort: 0.2 },
    ],
    ghostKey: "up",
    muscles: { neck: 1 },
    build(p, ctx) {
      const J = solve3(spec(p));
      const yF = P([0, 0, 0])[1];
      const pivot = P(J.neck), r = 24;
      const arcA = P(a3(J.neck, m3(tilt3(J.s, m3(J.ant, -1), 30), r))), arcB = P(a3(J.neck, m3(tilt3(J.s, m3(J.ant, -1), -74), r)));
      void pivot;
      const tuck = p.h < -66;
      const back = [...floorEls(yF, 30, 270), floorShadow(ctx, P([60, 0, 0])[0], yF, 64, 0.8),
        ...flatBenchEls(P, benchEnd, PELVIS[0] + 30),
        pth(`M${P2(arcA)}A${r} ${r} 0 0 1 ${P2(arcB)}`, "cue" + (tuck ? " on" : ""))];
      const els = back.concat(draw3D(J, cam, ctx.mus, []));
      const hd = P(J.head);
      return { els, J, labels: [
        { at: [hd[0] - 4, hd[1] - 34], text: "CHIN TO CHEST", on: tuck, anchor: "middle" },
        { at: [P(J.shoulder)[0] + 2, P([0, BENCH.top, 0])[1] + 18], text: "SHOULDERS STAY DOWN", on: false, anchor: "start" },
        { at: [hd[0] - 4, hd[1] + 30], text: ctx.phase === "Slow down" ? "SLOW ON THE WAY BACK" : "", on: true, anchor: "middle" },
      ] };
    },
  };
  calibrate3(cam, k => FIG.build(k, { mus: { __id: "cal" }, phase: "", pt: 0, seg: null, uid: "cal" }).J, sampleKeys(FIG));
  FIGS.push(FIG);
})();

/* =========================================================
   PHASE 2 · BATCH 2: cable machines (3D)
   Side-on figures face +x; the 2D side profiles keep them
   consistent with the rest. Front figures face the camera (+z).
   ========================================================= */
const FLOOR_C = 262;
const FACE_RIGHT = [0, 0, -1];             // lat hint: chest faces +x, L is the near side

// arm through a designed elbow: target the grip, aim the bend at the elbow
const via = (J, S, E, G) => ({ at: G, elbow: E, pole: s3(E, J["sh" + S]) });
const out3 = (J, S) => m3(J.lat, S === "R" ? 1 : -1);

// standing legs, side-on: ankles under the hips, optional stagger (near foot forward)
function standLegs(x = 0, stagger = 0, width = 11) {
  return {
    R: { ankle: [x - stagger, 8.4, -width], pole: [1, 0.2, 0], foot: [1, 0, 0] },
    L: { ankle: [x + stagger, 8.4, width], pole: [1, 0.2, 0], foot: [1, 0, 0] },
  };
}
// standing legs, facing the camera
function standLegsFront(stagger = 0, width = 11) {
  return {
    R: { ankle: [width, 8.4, -stagger], pole: [0.1, 0.2, 1], foot: [0.1, 0, 1] },
    L: { ankle: [-width, 8.4, stagger], pole: [-0.1, 0.2, 1], foot: [-0.1, 0, 1] },
  };
}
// weight stack column, side-on. face: x of the side facing the lifter
function towerSide(P, x0, x1, H, lift, exits) {
  const els = [];
  const a = P([x0, H, 0]), b = P([x1, 0, 0]);
  els.push(pth(roundRect(a[0], a[1], b[0] - a[0], b[1] - a[1], 1), "iron-dim"));
  els.push(pth(`M${r1(a[0] + 6)} ${r1(a[1] + 8)}V${r1(b[1] - 4)}M${r1(b[0] - 6)} ${r1(a[1] + 8)}V${r1(b[1] - 4)}`, "line-dim"));
  const n = 12, ph = 7.2, base = b[1] - 4;
  const cx = (a[0] + b[0]) / 2, top = P([(x0 + x1) / 2, H - 12, 0]);
  for (let i = 0; i < n; i++) {
    const lifted = i < 5, y = base - (n - i) * ph - (lifted ? lift : 0);
    els.push(pth(roundRect(a[0] + 6, y + 0.6, b[0] - a[0] - 12, ph - 1.2, 0.8), lifted && lift > 0.8 ? "lifted" : "iron-dim"));
  }
  const stackTop = base - n * ph - lift;
  els.push(pth(`M${r1(cx)} ${r1(top[1])}V${r1(stackTop)}`, "cable"));
  for (const e of exits) { const q = P(e); els.push(pth(`M${P2(q)}L${P2(top)}`, "cable")); }
  els.push(pth(circle(top, 5), "iron"));
  for (const e of exits) els.push(pth(circle(P(e), 4), "iron"));
  return els;
}
// a box in 3D, visible faces only
function box3(cam, mn, mx, cls) {
  const [x0, y0, z0] = mn, [x1, y1, z1] = mx;
  const faces = [
    [[1, 0, 0], [[x1, y0, z0], [x1, y1, z0], [x1, y1, z1], [x1, y0, z1]]],
    [[-1, 0, 0], [[x0, y0, z0], [x0, y1, z0], [x0, y1, z1], [x0, y0, z1]]],
    [[0, 0, 1], [[x0, y0, z1], [x0, y1, z1], [x1, y1, z1], [x1, y0, z1]]],
    [[0, 0, -1], [[x0, y0, z0], [x0, y1, z0], [x1, y1, z0], [x1, y0, z0]]],
    [[0, 1, 0], [[x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]]],
  ];
  return faces.filter(([nrm_]) => d3(nrm_, cam.toCam) > 0.02).map(([, q]) => pth(poly(q.map(cam.P)), cls));
}
const liftOf = (exit, grip, rest) => Math.max(0, (l3(s3(grip, exit)) - rest) * 0.55);
const calib = (cam, FIG) => calibrate3(cam, k => FIG.build(k, { mus: { __id: "cal" }, phase: "", pt: 0, seg: null, uid: "cal" }).J, sampleKeys(FIG));

/* ---- Tricep pushdown: face the stack, upper arms pinned, forearms from parallel to straight ---- */
(() => {
  const cam = camera3(0, 150, FLOOR_C, 0), P = cam.P;
  const S0 = n3([Math.sin(4 * D2R), Math.cos(4 * D2R), 0]);
  const EXIT = [60, 205, 0];
  const spec = p => ({
    pelvis: [0, 91.4, 0], spine: S0, lat: FACE_RIGHT, head: -4, legs: standLegs(0, 0),
    arms: J => {
      const o = {};
      for (const S of ["R", "L"]) {
        const sh = J["sh" + S], E = a3(sh, a3([31 * Math.sin(5 * D2R), -31 * Math.cos(5 * D2R), 0], m3(out3(J, S), -3)));
        const a = p.fa * D2R, G = a3(E, a3([33 * Math.sin(a), -33 * Math.cos(a), 0], m3(out3(J, S), lerp(-9, -5, p.fa / 100))));
        o[S] = via(J, S, E, G);
      }
      return o;
    },
  });
  let REST = 0;
  const FIG = {
    id: "tricep-pushdown", view: "SIDE",
    frame: { k: 1.16, cx: 170, cy: 138 },
    keys: { up: { fa: 100 }, down: { fa: 4 } },
    seq: [
      { label: "Press", dur: 1, from: "up", to: "down", ease: "inOut", effort: 1 },
      { label: "Squeeze", dur: 0.5, from: "down", to: "down", effort: 1 },
      { label: "Return", dur: 2, from: "down", to: "up", ease: "inOut", effort: 0.7 },
      { label: "Reset", dur: 0.3, from: "up", to: "up", effort: 0.3 },
    ],
    ghostKey: "down",
    muscles: { triceps: 1 },
    build(p, ctx) {
      const J = solve3(spec(p)), yF = P([0, 0, 0])[1];
      const G = mix3(J.gripR, J.gripL, 0.5);
      const lift = liftOf(EXIT, G, REST);
      const E = P(J.elbowL), Sh = P(J.shL);
      const back = [...floorEls(yF, 30, 270), floorShadow(ctx, 150, yF, 28), ...towerSide(P, 60, 96, 230, lift, [EXIT]),
        pth(`M${P2([E[0], Sh[1] - 6])}V${r1(E[1] + 14)}`, "cue" + (ctx.phase === "Press" || ctx.phase === "Squeeze" ? " on" : ""))];
      const rope = { depth: 999, tag: "rope", els: [pth(`M${P2(P(EXIT))}L${P2(P(G))}`, "cable"), pth(circle(P(G), 2.6), "iron")] };
      const els = back.concat(draw3D(J, cam, ctx.mus, [rope]));
      return { els, J, labels: [
        { at: [Sh[0] - 22, E[1] + 3], text: "ELBOWS PINNED", on: ctx.phase === "Press" || ctx.phase === "Squeeze", anchor: "end" },
        { at: [P(G)[0] + 8, P(G)[1] + 16], text: "FULL EXTENSION", on: p.fa < 8, anchor: "start" },
      ] };
    },
  };
  REST = l3(s3(mix3(solve3(spec(FIG.keys.up)).gripR, solve3(spec(FIG.keys.up)).gripL, 0.5), EXIT));
  calib(cam, FIG); FIGS.push(FIG);
})();

