/* ---- Hip abduction machine (front): pads outside the knees, torso leaned slightly forward ---- */
(() => {
  const cam = camera3(14, 150, 262, -16), P = cam.P;
  const SEAT = 48, PEL = [0, SEAT + 12.4, 0];
  const S0 = n3([0, Math.cos(14 * D2R), Math.sin(14 * D2R)]);    // lean toward the camera (forward)
  const knees = th => {
    const o = {};
    for (const [S, sg] of [["R", 1], ["L", -1]]) {
      const hip = [sg * 8.6, PEL[1], 0];
      const kn = a3(hip, [sg * B.thigh * Math.sin(th * D2R), -2, B.thigh * Math.cos(th * D2R)]);
      o[S] = { knee: kn, ankle: a3(kn, [0, -B.shin, 2]), pole: [sg, 0, 1], foot: [sg * 0.15, 0, 1] };
    }
    return o;
  };
  const FIG = {
    id: "hip-abduction", view: "FRONT",
    frame: { k: 1.42, cx: 150, cy: 186 },
    keys: { in: { th: 1 }, out: { th: 26 } }, ghostKey: "out",
    seq: [
      { label: "Out", dur: 1, from: "in", to: "out", ease: "inOut", effort: 1 },
      { label: "Hold", dur: 1.2, from: "out", to: "out", effort: 1 },
      { label: "Resist in", dur: 2, from: "out", to: "in", ease: "inOut", effort: 0.7 },
      { label: "Reset", dur: 0.3, from: "in", to: "in", effort: 0.3 },
    ],
    muscles: { abductors: 1, glutes: 0.6 },
    build(p, ctx) {
      const J = solve3({ pelvis: PEL, spine: S0, head: -6, legs: knees(p.th),
        arms: J0 => { const o = {}; for (const [S, sg] of [["R", 1], ["L", -1]]) o[S] = { at: [sg * 25, SEAT + 6, 8], pole: [sg, -0.4, -0.5] }; return o; } });
      const yF = P([0, 0, 0])[1];
      const items = [
        { depth: -60, tag: "seat", els: [...box3(cam, [-22, SEAT - 6, -22], [22, SEAT, 14], "iron"), ...box3(cam, [-20, SEAT, -26], [20, SEAT + 62, -20], "iron")] },
      ];
      for (const [S, sg] of [["R", 1], ["L", -1]]) {
        const kn = J["knee" + S], padC = a3(kn, [sg * 9, 0, -2]);
        items.push({ depth: cam.depth(padC) + 6, tag: "pad" + S, els: box3(cam, a3(padC, [-2, -9, -9]), a3(padC, [2, 9, 9]), "iron") });
        items.push({ depth: cam.depth(J["ankle" + S]) - 4, tag: "rest" + S, els: box3(cam, a3(J["ankle" + S], [-7, -9, -2]), a3(J["ankle" + S], [7, -7, 18]), "iron-dim") });
      }
      const els = [...floorEls(yF, 20, 280), floorShadow(ctx, 150, yF, 40, 0.8, 0.4)].concat(draw3D(J, cam, ctx.mus, items));
      const tot = Math.round(2 * p.th);
      const kR = P(J.kneeR), kL = P(J.kneeL);
      return { els, J, labels: [
        { at: [(kR[0] + kL[0]) / 2, Math.max(kR[1], kL[1]) + 30], text: `${tot}° APART`, on: p.th > 22, anchor: "middle" },
        { at: [150, P(J.head)[1] - 26], text: "LEAN FORWARD", on: true, anchor: "middle" },
      ] };
    },
  };
  calib(cam, FIG); FIGS.push(FIG);
})();

