/* ---- Dead hang: a hold, not a rep. Shoulders engaged, a slow breath, a timer.
   One minute runs in 15 seconds; past 60 s the tip says add scapular pulls. ---- */
(() => {
  const BAR = HANG_BAR, HOLD = 60, PERIOD = 15, BREATH = 3.2;
  const legs = { thighN: 177, shinN: 183, footN: 166, thighF: 180, shinF: 188, footF: 171 };
  const at = t => {
    const b = 0.5 - 0.5 * Math.cos(2 * Math.PI * t / BREATH);          // 0 exhale, 1 inhale
    const sway = 0.7 * Math.sin(2 * Math.PI * t / (BREATH * 2.5));
    return Object.assign({ trunk: -3 + sway - 0.8 * b, head: 0, anchor: [145, BAR[1] + 61.2 - 0.6 * b] }, legs);
  };
  FIGS.push({
    id: "dead-hang", view: "SIDE",
    frame: { k: 1, cx: 150, cy: 162 },
    procedural: true, noGhost: true,
    period: PERIOD,
    seqLabels: [{ label: "Hold", dur: PERIOD }],
    muscles: { forearms: 1, lats: 0.45, traps: 0.3 },
    build(_p, ctx) {
      const J = solveSide(at(ctx.time), "shoulder", hangHands(BAR, [1, 0.8]));
      const secs = Math.min(HOLD, Math.floor((ctx.time % PERIOD) / PERIOD * (HOLD + 1)));
      const mmss = `0:${String(secs).padStart(2, "0")}`.replace("0:60", "1:00");
      // gap between ear and shoulder: shoulders down, not shrugged
      const ear = J.H([-1.6, 0.6]), sh = J.shoulder;
      const gap = pth(`M${P(add(ear, [-7, 0]))}H${r1(ear[0] - 15)}M${P(add(sh, [-7, -2]))}H${r1(ear[0] - 15)}M${r1(ear[0] - 12)} ${r1(ear[1])}V${r1(sh[1] - 2)}`, "cue on", "stroke-dasharray:none");
      const els = drawSide(J, ctx.mus, {
        back: [...floorEls(HANG_FLOOR, 40, 260), floorShadow(ctx, 146, HANG_FLOOR, 26, 0.45), ...hangRig(BAR), gap],
        front: hangBarEls(BAR),
      });
      return { els, J, count: `${mmss} / 1:00`, tempoLabel: `Hold · ${mmss}`, labels: [
        { at: [ear[0] - 16, (ear[1] + sh[1]) / 2 + 3], text: "SHOULDERS DOWN", on: true, anchor: "end" },
        { at: [BAR[0] + 10, BAR[1] - 6], text: "FULL GRIP", on: false, anchor: "start" },
        { at: [164, HANG_FLOOR - 26], text: secs >= 55 ? "60 S: ADD SCAP PULLS" : "", on: true, anchor: "start" },
      ] };
    },
    ghostTime: 0,
  });
})();

